package com.procurement.purchaseorder.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="purchase_order_attachments")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class PurchaseOrderAttachment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="purchase_order_attachment_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_id",nullable=false)private PurchaseOrder purchaseOrder;@Column(name="file_name",nullable=false)private String fileName;@Column(name="file_path",nullable=false,length=1000)private String filePath;@Column(name="file_type",nullable=false)private String fileType;@Column(name="uploaded_at",nullable=false)private LocalDateTime uploadedAt;@PrePersist void pre(){if(uploadedAt==null)uploadedAt=LocalDateTime.now();}}
